"""Verify the lab is solved by checking the home page."""
from suite import ExploitSession

class Verify(ExploitSession):
    session_id = "verify"

    def check(self):
        resp = self.http.get("https://0a90006604707e3e80a3491400b0000e.web-security-academy.net/")
        if "is-solved" in resp.text:
            self.p("CONFIRMED: Lab is solved!")
        elif "Congratulations" in resp.text:
            self.p("CONFIRMED: Lab is solved (congratulations message)!")
        else:
            self.p("Lab status unclear, checking for solved indicator...")
            # Look for the lab header section
            import re
            match = re.search(r'widgetcontainer-lab-status\s+(\S+)', resp.text)
            if match:
                self.p(f"Lab status class: {match.group(1)}")
            else:
                self.p("Could not find lab status indicator")

t = Verify()
t.check()

